def semver_sort(versions):
    def parse(v):
        # split build metadata
        main_part = v
        if '+' in v:
            main_part = v.split('+', 1)[0]
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core, prerelease = main_part, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre = 0
            ids = prerelease.split('.')
            pre_key = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in ids
            )

        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

